#include "bits/stdc++.h"

#define rep(i, n) for(int i = 0; i < (n); ++i)
#define all(a) (a).begin(), (a).end()

using namespace std;

using ll = long long;
using vl = vector<ll>;
using vi = vector<int>;
const int INFi  = 2e9;

const int N = 1e5 + 5;
vector<pair<int, int>> g[N];
int dp[N];

void dfs(int v, int p, int px) {
    int c = 0;
    dp[v] = 0;
    for (auto &[u, x] : g[v]) {
        if (u == p) continue;
        dfs(u, v, x);
        dp[v] += dp[u];
        if (x == 1) c += 1;
    }
    dp[v] -= c / 2;
    c %= 2;
    if (c != px) {
        if (c == 0) {
            dp[v]++;
        }
    }
}

int ans = INFi;
void solve(int v) {
    dp[v] = 0;
    int c = 0;
    for (auto &[u, x] : g[v]) {
        dp[v] += dp[u];
        if (x == 1) c += 1;
    }
    dp[v] -= c / 2;
    ans = min(ans, dp[v]);
}

void reroot(int v, int p) {
    solve(v);
    int sum = 0;
    int c = 0;
    for (auto &[u, x] : g[v]) sum += dp[u];
    for (auto &[u, x] : g[v]) c += x;

    for (auto &[u, x] : g[v]) {
        if (u == p) continue;

        int sum2 = sum - dp[u];
        int c2 = c - x;
        int y = x ^ 1;
        dp[v] = sum2 - (c2 / 2);
        c2 %= 2;
        if (c2 == 0 && y == 1) {
            dp[v]++;
        }

        reroot(u, v);
    }
}

void solve() {
    int n; cin >> n;
    rep(_, n - 1) {
        int u, v; cin >> u >> v;
        g[u].push_back({v, 1});
        g[v].push_back({u, 0});
    }

    dfs(1, -1, 0);
    reroot(1, -1);

    cout << ans << '\n';

    ans = INFi;
    rep(i, n + 1) g[i].clear();
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    int t = 1;
    cin >> t;
    while (t--) {
        solve();
    }
    return 0;
}
